            "NC": "North Carolina",
            "ND": "North Dakota",
            "OH": "Ohio",
            "OK": "Oklahoma",
            "OR": "Oregon",
            "PA": "Pennsylvania",
            "RI": "Rhode Island",
            "SC": "South Carolina",
            "SD": "South Dakota",
            "TN": "Tennessee",
            "TX": "Texas",
            "UT": "Utah",
            "VT": "Vermont",
            "VA": "Virginia",
            "WA": "Washington",
            "WV": "West Virginia",
            "WI": "Wisconsin",
            "WY": "Wyoming",
            "DC": "District of Columbia",
        }

        def _normalize_state_abbrevs(text: str) -> str:
            def _repl(m):
                city = m.group(1).strip()
                abbr = m.group(2).upper().rstrip(".")
                state = state_map.get(abbr)
                if not state:
                    return m.group(0)
                return f"{city}, {state}"

            text = re.sub(r"\b([A-Z][A-Za-z .'\-]+),\s*([A-Z]{2})\b", _repl, text)
            text = re.sub(r"\b([A-Z][A-Za-z .'\-]+)\s+([A-Z]{2})\b", _repl, text)

def rule_principal_offices_press_release_dateline(doc: dict) -> list[dict]:
    """Return the press-release dateline when the filing is a first-page 8-K/news release style document."""
    try:
        import re

        full_text = " ".join((doc.get("text") or "").split())
        if not full_text:
            return []

        dateline_re = re.compile(
            r"\b[A-Z][A-Za-z .&'\-]+,\s*[A-Z][a-z]{1,3}\.?,\s*[A-Z][a-z]+\.?\s+\d{1,2},\s+\d{4}\b"
        )

        m = dateline_re.search(full_text)
        if m:
            return [{"text": " ".join(m.group(0).split())}]

        return []
    except Exception:
        return []

